/**
 * Receipt fixtures for the film-led verifier.
 *
 * These are the published cool.receipt.v1 conformance vectors in
 * `public/cool-vectors/`, generated by cool-sdk/scripts/generate-vectors.mjs
 * and never edited by hand. See README.md beside this file for provenance.
 *
 * They were sealed with the mock attestor (runtime.mode = "mock"), so the
 * verifier reports attestation MOCK and anchor/witnesses ABSENT on every one
 * of them. The UI says so; it must never imply these are hardware receipts.
 */

export interface Fixture {
  readonly id: string;
  readonly label: string;
  readonly path: string;
  readonly kind: "valid" | "tampered";
  /** The domain the published vector index says must fail. */
  readonly expectFail?: string;
}

export const FIXTURES: readonly Fixture[] = [
  {
    id: "valid",
    label: "Valid receipt · with inclusion proof",
    path: "/cool-vectors/valid-receipt-with-inclusion.json",
    kind: "valid",
  },
  {
    id: "mutated-output",
    label: "Tampered · output hash edited",
    path: "/cool-vectors/tampered/mutated-output.json",
    kind: "tampered",
    expectFail: "signature",
  },
  {
    id: "swapped-weights",
    label: "Tampered · model weights swapped",
    path: "/cool-vectors/tampered/swapped-weights-hash.json",
    kind: "tampered",
    expectFail: "signature",
  },
  {
    id: "corrupt-audit-path",
    label: "Tampered · log audit path corrupted",
    path: "/cool-vectors/tampered/corrupt-audit-path.json",
    kind: "tampered",
    expectFail: "inclusion",
  },
];

/** Limits a dropped file must satisfy before it is parsed. */
export const MAX_RECEIPT_BYTES = 256 * 1024;

export interface TamperResult {
  readonly receipt: unknown;
  readonly path: string;
  readonly before: string;
  readonly after: string;
  /** Character index of the flipped nibble within the field value. */
  readonly offset: number;
}

/** Fields the tamper action may target, in order of preference. */
const TAMPER_PATHS = [
  ["record", "response", "output_hash"],
  ["record", "request", "input_hash"],
  ["record", "model", "weights_hash"],
] as const;

/**
 * Flip exactly one hex digit of one committed hash in a deep copy of the
 * receipt. Deterministic: the last hex digit of the first available field,
 * so the same click always produces the same, reproducible tamper.
 */
export function tamperOneByte(receipt: unknown): TamperResult {
  const copy = structuredClone(receipt) as Record<string, unknown>;
  for (const path of TAMPER_PATHS) {
    let node: Record<string, unknown> | undefined = copy;
    for (const key of path.slice(0, -1)) {
      node = node?.[key] as Record<string, unknown> | undefined;
    }
    const leaf = path[path.length - 1] as string;
    const value = node?.[leaf];
    if (typeof value !== "string" || !node) continue;
    const offset = value.length - 1;
    const ch = value.charAt(offset);
    if (!/[0-9a-f]/.test(ch)) continue;
    const flipped = ((parseInt(ch, 16) ^ 0x1) & 0xf).toString(16);
    const after = value.slice(0, offset) + flipped;
    node[leaf] = after;
    return { receipt: copy, path: path.join("."), before: value, after, offset };
  }
  throw new Error("receipt has no tamperable hash field");
}
